package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

var update = flag.Bool("update", false, "rewrite the expected example reports")

var examples = filepath.Join("..", "..", "examples")

func runCLI(t *testing.T, args ...string) (int, string, string) {
	t.Helper()
	var out, errOut bytes.Buffer
	code := run(args, &out, &errOut)
	return code, out.String(), errOut.String()
}

// The example reports in examples/expected are generated by this test and
// must stay byte-for-byte reproducible.
func TestExampleReports(t *testing.T) {
	old := version
	version = "v0.1.0"
	t.Cleanup(func() { version = old })

	for _, tc := range []struct {
		manifest, name string
		code           int
	}{
		{"manifest.json", "report", exitPass},
		{"manifest-drift.json", "report-drift", exitFail},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			jsonPath := filepath.Join(dir, "r.json")
			htmlPath := filepath.Join(dir, "r.html")
			code, stdout, stderr := runCLI(t, "verify",
				"-manifest", filepath.Join(examples, tc.manifest),
				"-restored", filepath.Join(examples, "restored"),
				"-json", jsonPath, "-html", htmlPath)
			if code != tc.code {
				t.Fatalf("exit %d, want %d; stderr %s", code, tc.code, stderr)
			}
			for ext, got := range map[string]string{".json": jsonPath, ".html": htmlPath, ".txt": ""} {
				var data []byte
				if got == "" {
					data = []byte(stdout)
				} else {
					var err error
					if data, err = os.ReadFile(got); err != nil {
						t.Fatal(err)
					}
				}
				golden := filepath.Join(examples, "expected", tc.name+ext)
				if *update {
					if err := os.WriteFile(golden, data, 0o644); err != nil {
						t.Fatal(err)
					}
					continue
				}
				want, err := os.ReadFile(golden)
				if err != nil {
					t.Fatalf("%v (run go test ./cmd/restore-evidence -update)", err)
				}
				if !bytes.Equal(data, want) {
					t.Errorf("%s differs from %s (run go test ./cmd/restore-evidence -update)", ext, golden)
				}
			}
		})
	}
}

func TestExitCodes(t *testing.T) {
	m := filepath.Join(examples, "manifest.json")
	restored := filepath.Join(examples, "restored")
	cases := []struct {
		name string
		args []string
		code int
	}{
		{"no args", nil, exitError},
		{"unknown command", []string{"frobnicate"}, exitError},
		{"version", []string{"version"}, exitPass},
		{"help", []string{"help"}, exitPass},
		{"verify help", []string{"verify", "-h"}, exitPass},
		{"validate ok", []string{"validate", "-manifest", m}, exitPass},
		{"validate missing flag", []string{"validate"}, exitError},
		{"verify missing flag", []string{"verify"}, exitError},
		{"positional args", []string{"verify", "-manifest", m, "extra"}, exitError},
		{"pass", []string{"verify", "-manifest", m, "-restored", restored}, exitPass},
		{"fail", []string{"verify", "-manifest", filepath.Join(examples, "manifest-drift.json"), "-restored", restored}, exitFail},
		{"incomplete without directory", []string{"verify", "-manifest", m}, exitIncomplete},
		{"incomplete without hashing", []string{"verify", "-manifest", m, "-restored", restored, "-no-hash"}, exitIncomplete},
		{"missing restored dir", []string{"verify", "-manifest", m, "-restored", filepath.Join(restored, "nope")}, exitError},
		{"both outputs to stdout", []string{"verify", "-manifest", m, "-json", "-", "-html", "-"}, exitError},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			code, _, stderr := runCLI(t, tc.args...)
			if code != tc.code {
				t.Errorf("exit %d, want %d; stderr: %s", code, tc.code, stderr)
			}
		})
	}
}

func TestInvalidManifestExitCode(t *testing.T) {
	dir := t.TempDir()
	bad := filepath.Join(dir, "bad.json")
	os.WriteFile(bad, []byte(`{"schema_version":1,"test":{"id":"a","title":"b"},"files":[{"path":"../../etc/shadow"}]}`), 0o644)
	for _, cmd := range []string{"validate", "verify"} {
		code, _, stderr := runCLI(t, cmd, "-manifest", bad)
		if code != exitError || !strings.Contains(stderr, `".." segments`) {
			t.Errorf("%s: exit %d, stderr %s", cmd, code, stderr)
		}
	}
}

func TestJSONToStdout(t *testing.T) {
	code, stdout, stderr := runCLI(t, "verify", "-manifest", filepath.Join(examples, "manifest.json"),
		"-restored", filepath.Join(examples, "restored"), "-json", "-")
	if code != exitPass {
		t.Fatalf("exit %d: %s", code, stderr)
	}
	var r map[string]any
	if err := json.Unmarshal([]byte(stdout), &r); err != nil {
		t.Fatalf("stdout is not only JSON: %v", err)
	}
	if !strings.Contains(stderr, "Restore test RT-EXAMPLE-001: pass") {
		t.Errorf("summary not on stderr: %q", stderr)
	}
}

func TestOutputSafety(t *testing.T) {
	m := filepath.Join(examples, "manifest.json")
	dir := t.TempDir()
	out := filepath.Join(dir, "r.json")

	if code, _, stderr := runCLI(t, "verify", "-manifest", m, "-json", out, "-html", out); code != exitError {
		t.Errorf("same path for both outputs accepted: %s", stderr)
	}
	os.WriteFile(out, []byte("keep"), 0o644)
	if code, _, _ := runCLI(t, "verify", "-manifest", m, "-json", out); code != exitError {
		t.Error("existing report overwritten without -force")
	}
	if b, _ := os.ReadFile(out); string(b) != "keep" {
		t.Fatal("existing report modified")
	}
	if code, _, stderr := runCLI(t, "verify", "-manifest", m, "-json", out, "-force"); code != exitIncomplete {
		t.Errorf("-force: exit %d %s", code, stderr)
	}

	// Never write into the restored directory.
	restored := filepath.Join(dir, "restored")
	os.Mkdir(restored, 0o755)
	if code, _, stderr := runCLI(t, "verify", "-manifest", m, "-restored", restored, "-html", filepath.Join(restored, "r.html")); code != exitError ||
		!strings.Contains(stderr, "inside the restored directory") {
		t.Errorf("wrote inside restored directory: exit %d %s", code, stderr)
	}
	if entries, _ := os.ReadDir(restored); len(entries) != 0 {
		t.Fatalf("restored directory modified: %v", entries)
	}

	// Never replace the manifest, even with -force.
	mcopy := filepath.Join(dir, "m.json")
	data, _ := os.ReadFile(m)
	os.WriteFile(mcopy, data, 0o644)
	if code, _, _ := runCLI(t, "verify", "-manifest", mcopy, "-json", mcopy, "-force"); code != exitError {
		t.Error("manifest replaced by report")
	}
	if b, _ := os.ReadFile(mcopy); !bytes.Equal(b, data) {
		t.Fatal("manifest modified")
	}
}

// Commands in a manifest are documentation only.
func TestSuppliedCommandIsNotExecuted(t *testing.T) {
	dir := t.TempDir()
	marker := filepath.Join(dir, "executed")
	cmd := "touch " + marker + " && echo pwned > " + marker
	m := map[string]any{
		"schema_version": 1,
		"test":           map[string]any{"id": "T", "title": "T"},
		"supplied_results": []any{map[string]any{
			"id": "c", "description": "d", "outcome": "pass", "command": cmd,
		}},
	}
	data, _ := json.Marshal(m)
	mp := filepath.Join(dir, "m.json")
	os.WriteFile(mp, data, 0o644)
	code, stdout, stderr := runCLI(t, "verify", "-manifest", mp, "-json", "-")
	if code != exitPass {
		t.Fatalf("exit %d: %s", code, stderr)
	}
	if _, err := os.Stat(marker); err == nil {
		t.Fatal("the supplied command was executed")
	}
	if !strings.Contains(stdout, `"command": "touch `) {
		t.Error("command text was not recorded")
	}
}

// The program must not be able to start processes or open network
// connections. This checks the imports of every non-test source file.
func TestNoProcessOrNetworkImports(t *testing.T) {
	forbidden := map[string]bool{"os/exec": true, "net": true, "net/http": true, "net/rpc": true, "plugin": true, "syscall": true, "unsafe": true}
	root := filepath.Join("..", "..")
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() && (d.Name() == ".git" || d.Name() == "examples") {
			return filepath.SkipDir
		}
		if d.IsDir() || !strings.HasSuffix(p, ".go") || strings.HasSuffix(p, "_test.go") {
			return nil
		}
		f, err := parser.ParseFile(token.NewFileSet(), p, nil, parser.ImportsOnly)
		if err != nil {
			return err
		}
		for _, imp := range f.Imports {
			path, _ := strconv.Unquote(imp.Path.Value)
			if forbidden[path] || strings.HasPrefix(path, "net/") {
				t.Errorf("%s imports %s", p, path)
			}
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
}
